from html.parser import HTMLParser
from pathlib import Path
class P(HTMLParser):
  def __init__(self): super().__init__(); self.inh=False; self.title=[]; self.href=None; self.active=False
  def handle_starttag(self,t,a):
    d=dict(a)
    if t=='li' and d.get('class')=='b_algo': self.active=True; self.href=None
    if self.active and t=='h2': self.inh=True
    if self.active and t=='a' and self.href is None and 'href' in d: self.href=d['href']
  def handle_endtag(self,t):
    if t=='h2': self.inh=False
    if t=='li' and self.active:
      print(' | '.join(self.title).strip(), '|', self.href)
      self.title=[]; self.active=False
  def handle_data(self,d):
    if self.active and self.inh: self.title.append(' '.join(d.split()))
for f in ['bing1.html','bing2.html']:
 print('FILE',f); P().feed(Path(f).read_text(errors='ignore'))
